    public :: sdl_hint_callback

    abstract interface
        ! void SDL_HintCallback(void *userdata, const char *name, const char *oldValue, const char *newValue)
        subroutine sdl_hint_callback(user_data, name, old_value, new_value) bind(c)
            import :: c_ptr
            implicit none
            type(c_ptr), intent(in), value :: user_data
            type(c_ptr), intent(in), value :: name
